/bin/bash -lc "python - <<'PY'
from PyQt5.QtCore import QUrl
u=QUrl('http://ex%33mple.com:8080/p%3A5/%C3%A4?x=%3A10&y=%20#%3A11')
for name in ('host','path','query','fragment'):
 f=getattr(u,name)
 for mode in (QUrl.PrettyDecoded,QUrl.FullyEncoded,QUrl.FullyDecoded):
  try: print(name,mode,f(mode))
  except Exception as e: print(name,mode,type(e).__name__,e)
print('encoded',u.toEncoded().data())
for name,value in [('setPath','/p%3A6/%C3%A4'),('setQuery','x=%3A11&y=%20'),('setFragment','%3A12'),('setHost','ex%34mple.com')]:
 v=QUrl(u)
 try:
  getattr(v,name)(value,QUrl.StrictMode)
  print(name,'strict',v.toEncoded().data())
 except Exception as e: print(name,'strict',type(e).__name__,e)
 v=QUrl(u)
 getattr(v,name)(value)
 print(name,'default',v.toEncoded().data())
PY"

